const axios = require('axios');
const fs = require('fs');

// Read .env.test
const envTest = fs.readFileSync('.env.test', 'utf8');
const envLines = envTest.trim().split('\n');
const secrets = {};

evLines.forEach(line => {
  if (line && !line.startsWith('#')) {
    const [key, value] = line.split('=');
    secrets[key] = value;
  }
});

// POST to CI endpoint
axios.post('http://localhost:47301/api/ci-secret-sync', secrets)
  .then(() => {
    console.log('CI secret sync completed successfully');
    process.exit(0);
  })
  .catch(err => {
    console.error('CI secret sync failed:', err.response?.data || err.message);
    process.exit(1);
  });

